/*
 * A119485  Number of children for which any subset can be generated by a
 *          counting-out game.
 * https://oeis.org/A119485
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, more
 * Formula:   not stated
 * Range:     u8 none, u16 none, u32 n <= 21, u64 n <= 21, u128 n <= 21,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* This function returns a(n), the nth positive integer that is either
   a prime, a double prime (2 × prime), or a power of two.
   The sequence is generated by sieving for primes up to a sufficiently
   large bound, forming the list of primes, double‑primes and powers of
   two, sorting it, removing duplicates, and storing the result in a
   static table. The table is rebuilt with a larger bound only if a
   requested index exceeds the current size.  */

#include <stdlib.h>
#include <stdbool.h>
#include <string.h>
#include <stddef.h>

/* Forward declarations of the external types */
#ifndef seq_t
/* seq_t will be defined by the build system (e.g., uint8_t, uint64_t, etc.) */
#endif
#ifndef idx_t
/* idx_t will be defined by the build system (e.g., uint64_t) */
#endif

/* static table of precomputed sequence values */
static seq_t *seq_vals = NULL;
static size_t seq_len = 0;
static bool seq_built = false;
static idx_t current_bound = 400000; /* initial sieve limit */

/* comparison function for qsort */
static int cmp_seq(const void *p1, const void *p2)
{
    const seq_t *a = (const seq_t *)p1;
    const seq_t *b = (const seq_t *)p2;
    if (*a < *b) return -1;
    if (*a > *b) return 1;
    return 0;
}

/* dynamic vector for building the list */
struct vec
{
    seq_t *a;
    size_t sz;
    size_t cap;
};

static void vec_init(struct vec *v, size_t start_cap)
{
    v->sz = 0;
    v->cap = start_cap > 0 ? start_cap : 16;
    v->a = (seq_t *)malloc(v->cap * sizeof(seq_t));
}

static void vec_push(struct vec *v, seq_t val)
{
    if (v->sz == v->cap) {
        v->cap <<= 1;
        seq_t *tmp = (seq_t *)realloc(v->a, v->cap * sizeof(seq_t));
        if (!tmp) { free(v->a); exit(EXIT_FAILURE); }
        v->a = tmp;
    }
    v->a[v->sz++] = val;
}

/* Build the sequence up to a given bound; rebuilds from scratch. */
static void build_up_to(idx_t bound)
{
    /* Sieve of Eratosthenes */
    bool *is_prime = (bool *)malloc((bound + 1) * sizeof(bool));
    if (!is_prime) exit(EXIT_FAILURE);
    memset(is_prime, 1, (bound + 1) * sizeof(bool));
    if (bound >= 0) is_prime[0] = false;
    if (bound >= 1) is_prime[1] = false;

    for (idx_t i = 2; i <= bound / i; ++i) {
        if (is_prime[i]) {
            for (idx_t j = i * i; j <= bound; j += i)
                is_prime[j] = false;
        }
    }

    /* Build vector of candidate numbers */
    struct vec v;
    vec_init(&v, 16);

    /* powers of two */
    for (seq_t p = 1; p <= bound; p <<= 1)
        vec_push(&v, p);

    /* primes and double primes */
    for (idx_t i = 2; i <= bound; ++i) {
        if (is_prime[i]) {
            vec_push(&v, (seq_t)i);
            if (i <= bound / 2)
                vec_push(&v, (seq_t)(i * 2));
        }
    }

    free(is_prime);

    /* Sort vector */
    qsort(v.a, v.sz, sizeof(seq_t), cmp_seq);

    /* Remove duplicates in place */
    size_t uniq = 0;
    for (size_t i = 0; i < v.sz; ++i) {
        if (uniq == 0 || v.a[uniq - 1] != v.a[i])
            v.a[uniq++] = v.a[i];
    }
    v.sz = uniq;

    /* Free old table if any and replace */
    free(seq_vals);
    seq_vals = v.a;
    seq_len = v.sz;
    seq_built = true;
    current_bound = bound;
}

/* Main sequence function */
seq_t a(idx_t n)
{
    if (n == 0)
        return 0;    /* undefined for index 0, return 0 for safety */

    /* Initial build */
    if (!seq_built) {
        build_up_to(current_bound);
    }

    /* Extend if necessary */
    if (n > seq_len) {
        while (seq_len < n) {
            current_bound <<= 1;          /* double the bound */
            build_up_to(current_bound);   /* rebuild with larger bound */
        }
    }

    return seq_vals[n - 1];
}
